SET LOCAL enable_seqscan = off;
CREATE FUNCTION pg_temp.plan_of(q text) RETURNS text AS $$ DECLARE r text; t text := ''; BEGIN FOR r IN EXECUTE 'EXPLAIN ' || q LOOP t := t || r || E'\n'; END LOOP; RETURN t; END $$ LANGUAGE plpgsql;
SELECT x.idx, x.method, x.is_unique, x.is_partial, x.key_cols, x.predicate, (pg_temp.plan_of('SELECT * FROM person WHERE UPPER(name) = ''ANNA''') LIKE '%Index Scan using idx_person_name%') AS used_in_plan FROM (SELECT 1) d LEFT JOIN (SELECT c.relname AS idx, am.amname AS method, i.indisunique AS is_unique, (i.indpred IS NOT NULL) AS is_partial, (SELECT string_agg(pg_get_indexdef(i.indexrelid, n, true), ', ' ORDER BY n) FROM generate_series(1, i.indnkeyatts) n) AS key_cols, pg_get_expr(i.indpred, i.indrelid) AS predicate FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_am am ON am.oid = c.relam WHERE c.relname = 'idx_person_name' AND c.relnamespace = current_schema()::regnamespace) x ON true
